export function hexToHsl(hex){const [r,g,b]=hex.slice(1).match(/../g).map(v=>parseInt(v,16)/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min,l=(max+min)/2;let h=0,s=0;if(d){s=d/(1-Math.abs(2*l-1));h=(max===r?(g-b)/d+(g<b?6:0):max===g?(b-r)/d+2:(r-g)/d+4)*60;}return [h,s*100,l*100];}
export function hslToHex(h,s,l){s/=100;l/=100;const c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs((h/60)%2-1)),m=l-c/2;const rgb=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return '#'+rgb.map(v=>Math.round((v+m)*255).toString(16).padStart(2,'0')).join('');}
export function openHslPicker(title,color,onChange){
 const dialog=document.createElement('dialog');dialog.className='hsl-dialog';dialog.setAttribute('aria-label',title+' HSL 色板');
 dialog.innerHTML='<div class="dialog-top"><h2></h2><button aria-label="关闭色板">✕</button></div><div class="hsl-plane"><canvas width="240" height="160" aria-label="饱和度与亮度色板"></canvas><span class="hsl-marker"></span></div><div class="hsl-sliders"></div><div class="hsl-value"><span class="hsl-preview"></span><label>HEX <input maxlength="7" aria-label="十六进制颜色"></label></div><p>拖动色板调整饱和度和亮度，滑块可精确调整 HSL。</p>';
 dialog.querySelector('h2').textContent=title;let values=hexToHsl(color);const canvas=dialog.querySelector('canvas'),ctx=canvas.getContext('2d'),inputs=[],outputs=[],marker=dialog.querySelector('.hsl-marker'),hex=dialog.querySelector('.hsl-value input');
 for(const [i,label,max] of [[0,'色相 H',360],[1,'饱和度 S',100],[2,'亮度 L',100]]){const row=document.createElement('label');row.className='hsl-row';row.textContent=label;const out=document.createElement('output'),input=document.createElement('input');input.type='range';input.min=0;input.max=max;input.step=1;input.setAttribute('aria-label',label);input.oninput=()=>{values[i]=Number(input.value);sync(i===0);};row.append(out,input);dialog.querySelector('.hsl-sliders').append(row);inputs.push(input);outputs.push(out);}
 function draw(){const image=ctx.createImageData(240,160);for(let y=0;y<160;y++)for(let x=0;x<240;x++){const rgb=hslToHex(values[0],x/239*100,(1-y/159)*100);const k=(y*240+x)*4;for(let a=0;a<3;a++)image.data[k+a]=parseInt(rgb.slice(1+a*2,3+a*2),16);image.data[k+3]=255;}ctx.putImageData(image,0,0);}
 function sync(redraw=true,notify=true){const next=hslToHex(...values);inputs.forEach((input,i)=>{input.value=values[i];outputs[i].textContent=Math.round(values[i])+(i?'%':'°');});hex.value=next;dialog.querySelector('.hsl-preview').style.background=next;marker.style.left=values[1]+'%';marker.style.top=(100-values[2])+'%';if(redraw)draw();if(notify)onChange(next);}
 function point(e){const r=canvas.getBoundingClientRect();values[1]=Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100));values[2]=Math.max(0,Math.min(100,100-(e.clientY-r.top)/r.height*100));sync(false);}
 canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);point(e);};canvas.onpointermove=e=>{if(canvas.hasPointerCapture(e.pointerId))point(e);};canvas.onpointerup=e=>{if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);};
 hex.onchange=()=>{if(/^#[0-9a-f]{6}$/i.test(hex.value)){values=hexToHsl(hex.value);sync();}else sync(false,false);};
 dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();document.body.append(dialog);sync(true,false);dialog.showModal();
}
